//! Server-compatible JAR encoding (archiver 7's stored ZIP format).
//! Keep upstream entry order and executable bits; append new entries in name
//! order, drop signature metadata, and write fixed timestamps without extras.

use std::collections::{BTreeMap, BTreeSet};
use std::io::Cursor;

pub(crate) fn is_signature(name: &str) -> bool {
    let upper = name.to_ascii_uppercase();
    upper == ".SIGNATURE.P7S"
        || upper.strip_prefix("META-INF/").is_some_and(|n| {
            !n.contains('/')
                && [".SF", ".RSA", ".DSA", ".EC"]
                    .iter()
                    .any(|ext| n.ends_with(ext))
        })
}

/// Canonicalize a locally patched JAR using the upstream archive's ordering.
/// Both archives are decoded with the vendor verifier's size/entry limits.
pub(crate) fn canonical_jar(upstream: &[u8], patched: &[u8]) -> Result<Vec<u8>, String> {
    super::super::verify::read_zip_bytes_to_map(upstream)?;
    let mut bodies = super::super::verify::read_zip_bytes_to_map(patched)?;
    let mut original = zip::ZipArchive::new(Cursor::new(upstream)).map_err(|e| e.to_string())?;
    let mut order = Vec::new();
    let mut seen = BTreeSet::new();
    for i in 0..original.len() {
        let file = original.by_index(i).map_err(|e| e.to_string())?;
        if file.is_dir() {
            continue;
        }
        let name = file.name().to_string();
        if !seen.insert(name.clone()) {
            return Err(format!("duplicate upstream JAR entry: {name}"));
        }
        let mode = if file.unix_mode().is_some_and(|m| m & 0o111 != 0) {
            0o100755
        } else {
            0o100644
        };
        order.push((name, mode));
    }
    let mut additions: Vec<_> = bodies
        .keys()
        .filter(|name| !seen.contains(*name))
        .cloned()
        .collect();
    additions.sort();
    order.extend(additions.into_iter().map(|name| (name, 0o100644)));
    let mut patched_zip = zip::ZipArchive::new(Cursor::new(patched)).map_err(|e| e.to_string())?;
    let mut crcs = BTreeMap::new();
    for i in 0..patched_zip.len() {
        let file = patched_zip.by_index(i).map_err(|e| e.to_string())?;
        crcs.insert(file.name().to_string(), file.crc32());
    }
    let mut out = Vec::new();
    let mut directory = Vec::new();
    let mut count = 0u16;
    for (name, mode) in order {
        let Some(bytes) = bodies.remove(&name) else {
            continue;
        };
        if is_signature(&name) {
            continue;
        }
        let offset = u32::try_from(out.len()).map_err(|_| "JAR exceeds ZIP32 limits")?;
        let size = u32::try_from(bytes.len()).map_err(|_| "JAR member exceeds ZIP32 limits")?;
        let len = u16::try_from(name.len()).map_err(|_| "JAR member name too long")?;
        let flags = if name.is_ascii() { 0 } else { 0x800 };
        let crc = crcs[&name];
        u32s(&mut out, &[0x04034b50]);
        u16s(&mut out, &[10, flags, 0, 0, 33]);
        u32s(&mut out, &[crc, size, size]);
        u16s(&mut out, &[len, 0]);
        out.extend_from_slice(name.as_bytes());
        out.extend_from_slice(&bytes);
        u32s(&mut directory, &[0x02014b50]);
        u16s(&mut directory, &[0x032d, 10, flags, 0, 0, 33]);
        u32s(&mut directory, &[crc, size, size]);
        u16s(&mut directory, &[len, 0, 0, 0, 0]);
        u32s(&mut directory, &[(mode << 16) | 0x20, offset]);
        directory.extend_from_slice(name.as_bytes());
        count = count.checked_add(1).ok_or("too many JAR members")?;
    }
    let offset = u32::try_from(out.len()).map_err(|_| "JAR exceeds ZIP32 limits")?;
    let size = u32::try_from(directory.len()).map_err(|_| "JAR directory exceeds ZIP32 limits")?;
    out.extend_from_slice(&directory);
    u32s(&mut out, &[0x06054b50]);
    u16s(&mut out, &[0, 0, count, count]);
    u32s(&mut out, &[size, offset]);
    u16s(&mut out, &[0]);
    Ok(out)
}

fn u16s(out: &mut Vec<u8>, values: &[u16]) {
    for v in values {
        out.extend_from_slice(&v.to_le_bytes());
    }
}
fn u32s(out: &mut Vec<u8>, values: &[u32]) {
    for v in values {
        out.extend_from_slice(&v.to_le_bytes());
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::io::Write;

    #[test]
    fn matches_archiver_7_byte_for_byte() {
        // Fixture generated by fixtures/repack/generate.cjs.
        let expected = include_bytes!("fixtures/repack/archiver-7.0.1.jar");
        let mut upstream = zip::ZipWriter::new(Cursor::new(Vec::new()));
        for (name, bytes, mode) in [
            ("z.txt", "first\n", 0o644),
            ("META-INF/NOTICE.txt", "original\n", 0o644),
            ("bin/run", "exec\n", 0o755),
            ("café.txt", "unicode\n", 0o644),
            ("META-INF/SIGN.RSA", "signature", 0o644),
        ] {
            upstream
                .start_file(
                    name,
                    zip::write::SimpleFileOptions::default().unix_permissions(mode),
                )
                .unwrap();
            upstream.write_all(bytes.as_bytes()).unwrap();
        }
        let upstream = upstream.finish().unwrap().into_inner();
        let mut bodies = super::super::super::verify::read_zip_bytes_to_map(&upstream).unwrap();
        bodies.insert("META-INF/NOTICE.txt".into(), b"patched\n".to_vec());
        let mut entries: Vec<_> = bodies.into_iter().map(|(n, b)| (n, b, 0o644)).collect();
        entries.sort_by(|a, b| a.0.cmp(&b.0));
        let rebuilt = super::super::super::common::write_zip_entries(&entries).unwrap();
        assert_eq!(canonical_jar(&upstream, &rebuilt).unwrap(), expected);
        assert_eq!(canonical_jar(expected, expected).unwrap(), expected);
    }
}
